const event = items[0]?.json ?? {};
const workflow = event.workflow ?? {};
const execution = event.execution ?? {};
const trigger = event.trigger ?? {};
const error = execution.error ?? trigger.error ?? {};
const workflowName = workflow.name ?? workflow.id ?? 'unknown workflow';
const errorMessage = error.message ?? String(error) ?? 'unknown error';
const lastNode = execution.lastNodeExecuted ? `\nLast node: ${execution.lastNodeExecuted}` : '';
const mode = execution.mode ?? trigger.mode;
const modeLine = mode ? `\nMode: ${mode}` : '';
const executionId = execution.id ? `\nExecution: ${execution.id}` : '';

return [{ json: {
  topic: 'thornixos-ops',
  title: `n8n workflow failed: ${workflowName}`,
  message: `${errorMessage}${lastNode}${modeLine}${executionId}`,
  priority: 5,
  tags: ['rotating_light', 'n8n'],
  click: execution.url ?? 'https://loom.guildedthorn.arpa/home/workflows',
} }];
